INSERT INTO metric_definitions (metric_key, version, label, surface, unit, confidence, formula, session_basis, basis_label, grains, direction, comparison_mode, treatment, source_tables, effective_from, effective_to, change_note, created_at) VALUES
  ('refund_value', 2, 'Refunds', 'post_purchase', 'EGP', 'measured', 'Σ Shopify refunded amounts + Σ goods value on approved Yanet returns, by the order''s week', NULL, NULL, '["week","product","size","governorate","reason"]', 'lower_better', 'drop_day', 'Two channels, never double-counted: Shopify''s own refund amount, and an approved Yanet return, which the courier pays back in cash and Shopify never records. An approved request is treated as money out, because that is when the founder''s process releases it; a request still awaiting approval is not. At product, size and reason the Shopify half cannot be split into lines, so coverage states the share that is attributable.', '["fact_refund"]', '1970-01-02', NULL, 'v2: counts money returned through either channel — Shopify''s own refunds and approved Yanet returns paid back by the courier — and attributes it to the order''s week.', '2026-09-16T00:00:00Z'),
  ('refund_orders', 2, 'Refunded orders', 'post_purchase', 'count', 'measured', 'orders with money returned through either channel, by the order''s week', NULL, NULL, '["week","governorate"]', 'lower_better', 'drop_day', 'Two channels, never double-counted: Shopify''s own refund amount, and an approved Yanet return, which the courier pays back in cash and Shopify never records. An approved request is treated as money out, because that is when the founder''s process releases it; a request still awaiting approval is not.', '["fact_refund"]', '1970-01-02', NULL, 'v2: counts money returned through either channel — Shopify''s own refunds and approved Yanet returns paid back by the courier — and attributes it to the order''s week.', '2026-09-16T00:00:00Z'),
  ('refund_units', 2, 'Refunded units', 'post_purchase', 'count', 'measured', 'Σ units on approved Yanet returns', NULL, NULL, '["week","product","size","variant"]', 'lower_better', 'drop_day', 'Two channels, never double-counted: Shopify''s own refund amount, and an approved Yanet return, which the courier pays back in cash and Shopify never records. An approved request is treated as money out, because that is when the founder''s process releases it; a request still awaiting approval is not. Only the Yanet channel carries lines; a Shopify refund is an amount against the order, so units under-count where that channel is used.', '["fact_refund_line"]', '1970-01-02', NULL, 'v2: counts money returned through either channel — Shopify''s own refunds and approved Yanet returns paid back by the courier — and attributes it to the order''s week.', '2026-09-16T00:00:00Z'),
  ('refund_rate', 2, 'Refund rate', 'post_purchase', 'ratio', 'measured', 'orders with money returned ÷ delivered orders, by the order''s week', NULL, NULL, '["week","product","governorate","platform","campaign","adset","ad"]', 'lower_better', 'drop_day', 'Two channels, never double-counted: Shopify''s own refund amount, and an approved Yanet return, which the courier pays back in cash and Shopify never records. An approved request is treated as money out, because that is when the founder''s process releases it; a request still awaiting approval is not.', '["fact_refund","fact_order"]', '1970-01-02', NULL, 'v2: counts money returned through either channel — Shopify''s own refunds and approved Yanet returns paid back by the courier — and attributes it to the order''s week.', '2026-09-16T00:00:00Z'),
  ('contribution_margin', 2, 'Contribution margin', 'economics', 'EGP', 'modelled', 'gross_profit − ad_spend − fulfilment_cost_outbound − cod_collection_fees − rto_shipping_waste − refund_value', NULL, NULL, '["week","drop","offer"]', 'higher_better', 'drop_day', 'Modelled while any component is modelled (freight, COD fees). Refunds are subtracted whichever channel paid them; the returned item''s COGS is not credited back, because nothing yet records whether it was resold, so a restocked return reads worse than it was. The objective function (§0): delivered contribution margin per drop.', '["fact_order","fact_order_line","dim_variant","fact_ad_daily","fact_reversal","dim_geo"]', '1970-01-02', NULL, 'v2: subtracts refunds. Returns leave through the courier as well as Shopify, so a contribution line without them overstates every week that had one.', '2026-09-16T00:00:00Z');
